Think: Create the main executable src/date-format with a single-command shell script that uses awk to parse and format dates (supports several common patterns and tokens %Y, %m, %d, and %%). I'll create the file with a heredoc containing the script (the script's runtime is a single exec awk command).

Act: bash

```bash
cat > date-format/src/date-format <<'EOF'
#!/bin/sh
exec awk -v date="$1" -v fmt="$2" 'BEGIN{
  # Basic argument check
  if (date == "" || fmt == "") {
    print "Usage: date-format DATE FORMAT" > "/dev/stderr";
    exit 2;
  }
  y=""; m=""; d="";
  # YYYYMMDD
  if (date ~ /^[0-9]{8}$/) {
    y = substr(date,1,4); m = substr(date,5,2); d = substr(date,7,2);
  }
  # YYYY-M-D or YYYY/M/D or YYYY-MM-DD
  else if (match(date, /^([0-9]{4})[-\/]([0-9]{1,2})[-\/]([0-9]{1,2})$/, a)) {
    y = a[1]; m = a[2]; d = a[3];
  }
  # D-M-YYYY or D/M/YYYY
  else if (match(date, /^([0-9]{1,2})[-\/]([0-9]{1,2})[-\/]([0-9]{4})$/, a)) {
    d = a[1]; m = a[2]; y = a[3];
  }
  else {
    print "Invalid date: " date > "/dev/stderr";
    exit 2;
  }
  # Normalize numeric values and basic range checks
  mnum = m + 0; dnum = d + 0;
  if (mnum < 1 || mnum > 12 || dnum < 1 || dnum > 31) {
    print "Invalid date components" > "/dev/stderr";
    exit 2;
  }
  m2 = sprintf("%02d", mnum);
  d2 = sprintf("%02d", dnum);
  # Map format tokens: %Y, %m, %d, and %% -> %
  out = fmt;
  gsub(/%Y/, y, out);
  gsub(/%m/, m2, out);
  gsub(/%d/, d2, out);
  gsub(/%%/, "%", out);
  print out;
}'
EOF
```

