Think: Aggregate per-directory cumulative sizes and compute immediate-parent direct sums, flag any directories where cumulative sum is less than immediate direct sum, and write the sorted summary to temp_usr_check/usr_size_summary_preparation.txt.

Act: bash

```bash
awk -F, '{
 path=$1; size=$2+0;
 n=split(path,parts,"/");
 # compute parent directory (immediate parent)
 if(n<=2){ parent="/"; } else {
   parent="/";
   for(i=2;i<n;i++){ if(parent=="/") parent=parent parts[i]; else parent=parent "/" parts[i]; }
 }
 sum_direct[parent]+=size;
 s="";
 for(i=1;i<=n;i++){
   if(parts[i]=="") { s="/"; continue }
   if(s=="/") s=s parts[i]; else s=s "/" parts[i];
   dirsum[s]+=size;
 }
}
END{
 for(d in dirsum){
   flag = (dirsum[d] < sum_direct[d]) ? "DISCREPANCY" : "";
   printf "%s,%d,%d,%s\n", d, dirsum[d], (sum_direct[d]+0), flag;
 }
}' temp_usr_check/usr_sizes_raw.csv | sort -t, -k2 -nr > temp_usr_check/usr_size_summary_preparation.txt
```

