 /^siblings[[:space:]]*:/ && siblings=="" { split($0,a,":"); gsub(/^ +| +$/,"",a[2]); siblings=a[2] }
 /^model name[[:space:]]*:/ && model=="" { split($0,a,":"); sub(/^[ \t]+/,"",a[2]); sub(/[ \t]+$/,"",a[2]); model=a[2] }
END{
 if(arch=="") arch="UNKNOWN"
 if(lscpu_cpu=="") lscpu_cpu="UNKNOWN"
 print "ARCHITECTURE: " arch
 print "LSCPU_CPUs: " lscpu_cpu
 print "PROC_PROCESSOR_COUNT: " proc_count
